(function () {
  function resizeBloggerImages() {
    var w = window.innerWidth;
    var params;
    if (w < 576) {
      params = 'w480-h360-c';   // mobile 4:3
    } else if (w < 992) {
      params = 'w800-h450-c';   // tablet 16:9
    } else {
      params = 'w1200-h675-c';  // desktop 16:9
    }
    document.querySelectorAll('img[data-src]').forEach(function (img) {
      var src = img.getAttribute('data-src');
      if (!src) return;
      var rewritten = src
        .replace(/\/s\d+(-[^/]+)?\//, '/' + params + '/')
        .replace(/=s0$/, '=' + params);
      img.src = rewritten;
      img.removeAttribute('data-src');
      img.classList.add('img-loaded');
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', resizeBloggerImages);
  } else {
    resizeBloggerImages();
  }
})();
